-- Generated by rice-render for {{ meta.title }}. Linked to ~/.config/nvim/lua/rice/mode.lua.
-- Follows `rice mode`: when ~/.local/state/rice/mode changes, the rice
-- colourscheme is applied again (its link now leads to the other mode's
-- build) and lualine picks up its theme again. Started once per nvim by the
-- colourscheme. The folder is watched rather than the file, since `rice`
-- replaces the file by renaming a new one over it.
local M = {}

function M.apply()
  if vim.g.colors_name ~= "rice" then return end
  vim.cmd.colorscheme("rice")
  local ok, lualine = pcall(require, "lualine")
  if ok then
    package.loaded["lualine.themes.rice"] = nil
    pcall(lualine.setup, lualine.get_config())
  end
end

function M.watch()
  if M.handle then return end
  local uv = vim.uv or vim.loop
  local dir = (os.getenv("XDG_STATE_HOME") or (os.getenv("HOME") .. "/.local/state")) .. "/rice"
  local handle = uv.new_fs_event()
  if not handle then return end
  local ok = handle:start(dir, {}, vim.schedule_wrap(function(err, name)
    if not err and (name == nil or name == "mode") then M.apply() end
  end))
  if ok ~= 0 and ok ~= true then
    handle:close()
    return
  end
  M.handle = handle
end

return M
